mapper.select:
SELECT 
  FROM template t
  JOIN template_category c ON c.id = t.category_id
  LEFT JOIN template_translation tt
    ON tt.template_id = t.id AND tt.locale = #{locale}
  LEFT JOIN template_category_translation ct
    ON ct.category_id = c.id AND ct.locale = #{locale}
 WHERE t.is_published = 1

   AND t.category_id = #{categoryId}

 ORDER BY c.sort_order, t.sort_order, COALESCE(tt.title, t.title), t.id

SELECT 
  FROM template t
  JOIN template_category c ON c.id = t.category_id
  LEFT JOIN template_translation tt
    ON tt.template_id = t.id AND tt.locale = #{locale}
  LEFT JOIN template_category_translation ct
    ON ct.category_id = c.id AND ct.locale = #{locale}
 WHERE t.id = #{id}
   AND t.is_published = 1
